void func_8000C904(Window *w)
{
    int          i;
    int          x;
    int          y;
    int          left;
    int          top;
    unsigned int step;
    float        scale;
    float        max_x;
    float        max_y;
    float        x_end;
    float        strip_top;
    float        strip_bottom;
    float        clip_right;
    float        clip_bottom;
    int          right;
    int          bottom;
    int          s;
    int          t;
    float        ulx;
    float        uly;
    float        lrx;
    float        lry;
    float        pos_x;
    float        pos_y;
    float        line_bottom;

    x      = w->x;
    y      = w->y;
    scale  = w->scale;
    left   = w->clip_x0 + x;
    top    = w->clip_y0 + y;
    right  = w->clip_x1 + x;
    bottom = w->clip_y1 + y;
    x_end  = w->width + x;
    if (left < 0) {
        left = 0;
    }
    if (top < 0) {
        top = 0;
    }
    if (right < 0) {
        right = 0;
    }
    if (bottom < 0) {
        bottom = 0;
    }
    max_x = 320 / scale;
    max_y = 240 / scale;
    if (max_x < left) {
        left = max_x;
    }
    if (max_y < top) {
        top = max_y;
    }
    if (max_x < right) {
        right = max_x;
    }
    if (max_y < bottom) {
        bottom = max_y;
    }
    pos_x = x;
    pos_y = y;
    for (i = 0; i < w->strip_count; i++) {
        strip_top   = w->strip_height * i + y;
        line_bottom = w->strip_height * (i + 1) + y;
        if (right < x) {
            continue;
        }
        if (x_end < left) {
            continue;
        }
        if (line_bottom < top) {
            continue;
        }
        if (bottom < strip_top) {
            continue;
        }
        gDPLoadTLUT_pal16(g_sys_glistp++, 15, w->palette);
        gDPLoadTextureBlock_4b(g_sys_glistp++, w->texture + w->width * w->strip_height * i / 2, G_IM_FMT_CI, w->width,
            w->strip_height, 15, G_TX_WRAP | G_TX_NOMIRROR, G_TX_WRAP | G_TX_NOMIRROR, G_TX_NOMASK,
            G_TX_NOMASK, G_TX_NOLOD, G_TX_NOLOD);
        clip_right  = (right - left) * scale + left;
        clip_bottom = (bottom - top) * scale + top;
        step        = 1024.0f / scale;
        s           = (x < left) ? left - x : 0;
        t           = (strip_top < top) ? (int) (top - strip_top) : 0;
        x_end       = pos_x;
        x_end += w->width * scale;
        strip_top = pos_y;
        strip_top += w->strip_height * scale * i;
        strip_bottom = pos_y;
        strip_bottom += w->strip_height * scale * (i + 1);
        ulx = (left < x) ? pos_x : left;
        uly = (top < strip_top) ? strip_top : top;
        lrx = (x_end < clip_right) ? x_end : clip_right;
        lry = (strip_bottom < clip_bottom) ? strip_bottom : clip_bottom;
        gSPTextureRectangle(g_sys_glistp++, (int) (ulx * 4.0f), (int) (uly * 4.0f), (int) (lrx * 4.0f), (int) (lry * 4.0f),
            G_TX_RENDERTILE, s << 5, t << 5, step, step);
    }
}

